import threading
import time


class RateLimiter:
    def __init__(self, limit, window, clock=time.monotonic):
        self.limit = limit
        self.window = window
        self.clock = clock
        self._calls = {}
        self._lock = threading.Lock()

    def _recent(self, key, now):
        return [t for t in self._calls.get(key, []) if now - t < self.window]

    def allow(self, key):
        with self._lock:
            now = self.clock()
            recent = self._recent(key, now)
            allowed = len(recent) < self.limit
            if allowed:
                recent.append(now)
            self._calls[key] = recent
            return allowed

    def remaining(self, key):
        with self._lock:
            now = self.clock()
            return max(0, self.limit - len(self._recent(key, now)))

